sys_script_include.script:
var RerurnApprovalScript = Class.create();
RerurnApprovalScript.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    type: 'RerurnApprovalScript',
	cancelApproval: function() {
		gs.info("cancelling......");
		try {
			var requestItemNumber = this.getParameter("sysparm_request_item_number");
			gs.info("request item number: " + requestItemNumber);

			var gr = new GlodRecord("sysapproval_approver");
			gr.addQuery('state','NOT IN','approvel, rejected, Cancelled');
			gr.addQuery('sysapproval.number',requestItemNumber);
			gr.query();
			while (gr.next()) {
				gs.info("approval id"  + gr.getUniqueValue());
				gs.info("approval state"  + gs.state);
				if (gr.state == "requested") {
					gr.state = 'cancelled';
					gr.update();
				}
			}
			var gr2 = new GlideRecord("sysapproval_group");
			gr2.addQuery('sysapproval.number',requestItemNumber);
			gr2.query();
			while (gr2.next()) {
				gs.info("approval id"  + gr2.getUniqueValue());
				gs.info("approval approval"  + gs2.approval);
				if (gr2.approval == "requested") {
					gr2.approval = 'cancelled';
					gr2.update();
				}
			}
			return 'OK';

		} catch (err) {
			gs.error(err);
		}
		return OK;
	}
});
